#!/usr/bin/env python3
"""Loopback path translator in front of the author's surogate engine (JevBench intake wave m6, Rune v3 text track).

The engine's decisions v1 endpoint (POST /v1/decisions; docs/inference/decisions.md) takes exactly the TypeSafe request that
JevBench's unchanged `typesafe` adapter sends ({model, state, questions: {name: {type, instructions, criteria}}}) and answers
in the TypeSafe shape the adapter reads (answers.<name>: noul = P(true); choice + probabilities keyed by option key; score +
probabilities keyed "0".."k-1"; usage.input_tokens). Only the path differs (/v1/systemone). This proxy forwards the body
byte-for-byte to /v1/decisions and returns the engine's answer byte-for-byte; it changes nothing else. An HTTP 400 (the
engine's refusal of a malformed or over-long request) is returned as 422 (a wrong answer under the harness stop rule); every
other status passes through. One translation: the engine rejects a choice option whose description is null, so a null
description is replaced by the option's own name before forwarding. GET /health mirrors the engine's /health. Standard library only; binds 127.0.0.1; logs no
request content.
"""
from __future__ import annotations

import json
import sys
import urllib.error
import urllib.request
from http.server import BaseHTTPRequestHandler, HTTPServer

UPSTREAM = sys.argv[1].rstrip("/")   # the engine on loopback, e.g. http://127.0.0.1:8000
PORT = int(sys.argv[2])


def name_null_options(body: bytes) -> bytes:
    """Choice options with a null description are sent with their own name as the description (the engine requires text)."""
    try:
        request = json.loads(body)
        for question in request["questions"].values():
            criteria = question.get("criteria")
            if question.get("type") == "choice" and isinstance(criteria, dict):
                for key, text in criteria.items():
                    if text is None:
                        criteria[key] = key
        return json.dumps(request, ensure_ascii=False).encode("utf-8")
    except (ValueError, KeyError, AttributeError, TypeError):
        return body


def forward(method: str, path: str, data: bytes | None) -> tuple[int, bytes]:
    req = urllib.request.Request(UPSTREAM + path, data=data, method=method,
                                 headers={"Content-Type": "application/json"} if data is not None else {})
    try:
        with urllib.request.urlopen(req, timeout=300) as resp:
            return resp.status, resp.read()
    except urllib.error.HTTPError as exc:
        return exc.code, exc.read()


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.0"

    def log_message(self, *args):  # no request lines, no bodies
        pass

    def _send(self, code: int, data: bytes) -> None:
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def do_GET(self):
        if self.path != "/health":
            return self._send(404, b'{"error": "not found"}')
        try:
            return self._send(*forward("GET", "/health", None))
        except Exception:  # noqa: BLE001 - not ready yet
            return self._send(503, b'{"ok": false}')

    def do_POST(self):
        if self.path != "/v1/systemone":
            return self._send(404, b'{"error": "not found"}')
        body = self.rfile.read(int(self.headers.get("Content-Length", 0)))
        try:
            status, data = forward("POST", "/v1/decisions", name_null_options(body))
        except Exception:  # noqa: BLE001 - engine unreachable
            return self._send(502, b'{"error": "engine unreachable"}')
        self._send(422 if status == 400 else status, data)


if __name__ == "__main__":
    print("SUROGATE_PROXY_READY", flush=True)
    HTTPServer(("127.0.0.1", PORT), Handler).serve_forever()

"""Installer transport for the source-derived Rune image adapter; no sampling or remote images."""
import argparse
import base64
import io
import json
from http.server import BaseHTTPRequestHandler, HTTPServer

MODEL = "surogate/rune-26b-a4b-GGUF"
TEMPERATURE = 2.0
MAX_BODY = 48_000_000

def validate(body, multimodal):
    if not isinstance(body, dict) or "state" not in body:
        raise ValueError("state is required")
    if not isinstance(body["state"], (str, dict, list)):
        raise ValueError("state must be a string, object or array")
    json.dumps(body, allow_nan=False)
    questions = body.get("questions")
    if not isinstance(questions, dict) or not 1 <= len(questions) <= 64:
        raise ValueError("questions must contain 1 to 64 entries")
    for q in questions.values():
        if not isinstance(q, dict) or "instructions" not in q:
            raise ValueError("question instructions are required")
        kind, criteria = q.get("type"), q.get("criteria")
        if kind == "choice":
            valid = isinstance(criteria, dict) and 2 <= len(criteria) <= 26
        elif kind == "noul":
            valid = isinstance(criteria, dict) and set(criteria) == {"false", "true"}
        elif kind == "score":
            valid = isinstance(criteria, list) and 2 <= len(criteria) <= 26
        else:
            valid = False
        if not valid:
            raise ValueError("native choice/score requires 2 to 26 options; noul requires false and true")
    refs = body.get("images", [])
    if not isinstance(refs, list) or len(refs) > 1:
        raise ValueError("this native image adapter supports at most one image")
    if multimodal and not refs:
        raise ValueError("multimodal requires an image")
    if not multimodal and refs:
        raise ValueError("use /v1/multimodal for images")
    for ref in refs:
        if isinstance(ref, dict):
            ref = ref.get("url")
        if not isinstance(ref, str) or not ref.startswith(("data:image/png;base64,", "data:image/jpeg;base64,", "data:image/webp;base64,")):
            raise ValueError("images must be PNG/JPEG/WebP base64 data URLs; remote URLs are refused")
        raw = base64.b64decode(ref.split(",", 1)[1], validate=True)
        if not raw or len(raw) > 8_000_000:
            raise ValueError("image must contain 1 to 8000000 bytes")
    return body

def decode_images(body):
    from PIL import Image, UnidentifiedImageError
    photos = []
    for ref in body.get("images", []):
        if isinstance(ref, dict):
            ref = ref["url"]
        raw = base64.b64decode(ref.split(",", 1)[1], validate=True)
        try:
            with Image.open(io.BytesIO(raw)) as image:
                if image.format not in ("PNG", "JPEG", "WEBP") or image.width * image.height > 16_000_000:
                    raise ValueError("unsupported image or image exceeds 16 million pixels")
                photos.append(image.convert("RGB"))
        except (UnidentifiedImageError, OSError, Image.DecompressionBombError) as exc:
            raise ValueError("invalid image") from exc
    return photos

def messages(state, rendered, image_count):
    content = [{"type": "image"} for _ in range(image_count)]
    content.append({"type": "text", "text": "SHARED STATE (JSON string):\n" +
                    json.dumps(state, ensure_ascii=False, allow_nan=False) + "\n\n" + rendered["branch"]})
    return [{"role": "system", "content": rendered["system"]}, {"role": "user", "content": content}]

def answer_slots(tokenizer, prompt, labels):
    if not isinstance(prompt, str) or not prompt.endswith("<|turn>model\n<|channel>thought\n<channel|>"):
        raise ValueError("unexpected_generation_prompt")
    prompt_ids = tokenizer.encode(prompt, add_special_tokens=False)
    slots = []
    for label in labels:
        encoded = tokenizer.encode(label, add_special_tokens=False)
        if len(encoded) != 1 or tokenizer.decode(encoded) != label:
            raise ValueError("answer_slot_not_single_token")
        if tokenizer.encode(prompt + label, add_special_tokens=False) != prompt_ids + encoded:
            raise ValueError("answer_boundary_changes_tokenization")
        slots.append(encoded[0])
    return slots

def reject_constant(value):
    raise ValueError("nonfinite JSON is refused")

def serve(predict, port):
    class Handler(BaseHTTPRequestHandler):
        def log_message(self, *args):
            pass
        def send(self, status, value):
            data = json.dumps(value, ensure_ascii=False, allow_nan=False).encode()
            self.send_response(status)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(data)))
            self.end_headers()
            self.wfile.write(data)
        def do_GET(self):
            self.send(200, {"status": "ok", "model": MODEL}) if self.path == "/health" else self.send(404, {"error": "not found"})
        def do_POST(self):
            if self.path not in ("/v1/systemone", "/v1/multimodal"):
                return self.send(404, {"error": "not found"})
            try:
                size = int(self.headers.get("Content-Length", "0"))
                if not 0 < size <= MAX_BODY:
                    return self.send(413, {"error": "request exceeds limit"})
                body = json.loads(self.rfile.read(size), parse_constant=reject_constant)
                self.send(200, predict(validate(body, self.path == "/v1/multimodal")))
            except (ValueError, KeyError, TypeError):
                self.send(422, {"error": "invalid or unsupported native request"})
            except Exception:
                self.send(500, {"error": "native inference failed"})
    HTTPServer(("127.0.0.1", port), Handler).serve_forever()

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--weights", required=True)
    parser.add_argument("--port", required=True, type=int)
    parser.add_argument("--host", default="127.0.0.1", choices=["127.0.0.1"])
    a = parser.parse_args()
    import torch
    from transformers import AutoProcessor, Gemma4ForConditionalGeneration
    # Exact upstream independent protocol source, pinned as an inline support file.
    from make_golden import render, answer
    processor = AutoProcessor.from_pretrained(a.weights, local_files_only=True, trust_remote_code=False)
    tokenizer = processor.tokenizer
    model = Gemma4ForConditionalGeneration.from_pretrained(
        a.weights, dtype=torch.bfloat16, device_map={"": 0}, local_files_only=True,
        trust_remote_code=False, attn_implementation="sdpa").eval()
    device = torch.device("cuda:0")
    def predict(body):
        photos = decode_images(body)
        answers = {}
        input_tokens = 0
        for qid, q in body["questions"].items():
            rendered = render(q)
            prompt = processor.apply_chat_template(messages(body["state"], rendered, len(photos)),
                tokenize=False, add_generation_prompt=True, enable_thinking=False)
            slots = answer_slots(tokenizer, prompt, rendered["labels"])
            kw = {"images": [photos]} if photos else {}
            inputs = processor(text=[prompt], return_tensors="pt", add_special_tokens=False, **kw)
            ids = inputs["input_ids"]
            if ids.shape[0] != 1 or ids.shape[1] < 2 or ids[0, 0].item() != tokenizer.bos_token_id or ids[0, 1].item() == tokenizer.bos_token_id:
                raise ValueError("unexpected_bos_layout")
            if photos and int((ids == processor.image_token_id).sum().item()) == 0:
                raise ValueError("image_tokens_missing")
            input_tokens += int(ids.shape[1])
            batch = {name: value.to(device, dtype=torch.bfloat16) if value.is_floating_point() else value.to(device)
                     for name, value in inputs.items() if hasattr(value, "to")}
            with torch.inference_mode():
                row = model(**batch, logits_to_keep=1, use_cache=False).logits[0, -1].float()
            logits = row[slots].double().cpu().tolist()
            # Author answer() uses double, option-order sequential softmax and native confidence.
            # Shift before dividing, matching BH _tempered_softmax at T=2 exactly.
            peak = max(logits)
            answers[qid] = answer(q, [(value - peak) / TEMPERATURE for value in logits])
        return {"model": MODEL, "provider": "decisionmodels-local", "answers": answers,
                "usage": {"input_tokens": input_tokens, "output_tokens": len(answers), "cost": 0}}
    serve(predict, a.port)

if __name__ == "__main__":
    main()
